import os, json, time, numpy as np

SHARED = 'storage/shared/appxE_contribs'
OUT_DIR = 'storage/noesis/nmap'
OUT_RES = os.path.join(OUT_DIR, 'research', 'kkt_slack_cross_class_v2_1.json')

def _ts():
    return time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())

def _ensure():
    os.makedirs(os.path.join(OUT_DIR, 'research'), exist_ok=True)
    os.makedirs(os.path.join(OUT_DIR, 'freezes'), exist_ok=True)

def _class_key_from(fn):
    s = fn
    for tok in [
      '_slack_top_k_1e_9.json','_slack_top_k_1e_8.json',
      '_kkt_top_k_1e_9.json','_kkt_top_k_1e_8.json',
      '.json'
    ]:
        s = s.replace(tok, '')
    return s

def _is_pair(p):
    return isinstance(p, list) and len(p)==2 and all(isinstance(x, (int, np.integer)) for x in p)

def _read_pairs(path):
    try:
        data = json.load(open(path, 'r'))
    except Exception:
        return []
    pairs = []
    if isinstance(data, dict):
        if isinstance(data.get('pairs'), list):
            for p in data['pairs']:
                if _is_pair(p):
                    i, j = int(p[0]), int(p[1])
                    if i>j: i,j=j,i
                    pairs.append([i,j])
        else:
            for key in ['topk','data','items','list']:
                if isinstance(data.get(key), list):
                    for entry in data[key]:
                        if _is_pair(entry):
                            i,j = int(entry[0]), int(entry[1])
                            if i>j: i,j=j,i
                            pairs.append([i,j])
                        elif isinstance(entry, dict) and _is_pair(entry.get('pair')):
                            i,j = entry['pair']
                            i,j = int(i), int(j)
                            if i>j: i,j=j,i
                            pairs.append([i,j])
    elif isinstance(data, list):
        for p in data:
            if _is_pair(p):
                i,j = int(p[0]), int(p[1])
                if i>j: i,j=j,i
                pairs.append([i,j])
    # uniquify preserving order
    seen = set(); out=[]
    for i,j in pairs:
        t = (i,j)
        if t not in seen and 0<=i<j<26:
            out.append([i,j]); seen.add(t)
    return out

def _gather():
    files = []
    try:
        files = [f for f in os.listdir(SHARED) if f.endswith('.json')]
    except Exception:
        pass
    rec = {}
    for fn in files:
        key = _class_key_from(fn)
        r = rec.setdefault(key, {'slack':{'1e-9':None,'1e-8':None}, 'kkt':{'1e-9':None,'1e-8':None}})
        if fn.endswith('_slack_top_k_1e_9.json'):
            r['slack']['1e-9'] = os.path.join(SHARED, fn)
        elif fn.endswith('_slack_top_k_1e_8.json'):
            r['slack']['1e-8'] = os.path.join(SHARED, fn)
        elif fn.endswith('_kkt_top_k_1e_9.json'):
            r['kkt']['1e-9'] = os.path.join(SHARED, fn)
        elif fn.endswith('_kkt_top_k_1e_8.json'):
            r['kkt']['1e-8'] = os.path.join(SHARED, fn)
    return rec

def _jaccard(a, b):
    A = set(tuple(p) for p in a)
    B = set(tuple(p) for p in b)
    if not A and not B: return 1.0
    if not A or not B: return 0.0
    return float(len(A&B))/float(len(A|B))

def _spearman_on_intersection(a, b):
    idx_a = {tuple(p): i for i,p in enumerate(a)}
    idx_b = {tuple(p): i for i,p in enumerate(b)}
    inter = [p for p in idx_a if p in idx_b]
    n = len(inter)
    if n < 2: return None, n
    ra = np.array([idx_a[p] for p in inter], float); ra -= ra.mean()
    rb = np.array([idx_b[p] for p in inter], float); rb -= rb.mean()
    den = np.sqrt((ra**2).sum()) * np.sqrt((rb**2).sum())
    if den == 0: return None, n
    return float((ra*rb).sum()/den), n

def _analyze(rec):
    results = []
    for key, d in rec.items():
        entry = {'class': key, 'by_tol': {}}
        for tol in ['1e-9','1e-8']:
            kkt_path = d['kkt'][tol]
            slack_path = d['slack'][tol]
            if kkt_path and slack_path:
                kkt = _read_pairs(kkt_path)
                slack = _read_pairs(slack_path)
                # align by min length
                m = min(len(kkt), len(slack))
                kkt = kkt[:m]; slack = slack[:m]
                jac = _jaccard(kkt, slack)
                rho, n = _spearman_on_intersection(kkt, slack)
                entry['by_tol'][tol] = {
                    'K_used': m,
                    'kkt_file': kkt_path,
                    'slack_file': slack_path,
                    'jaccard': jac,
                    'spearman_on_intersection': rho,
                    'n_intersection': n
                }
            else:
                entry['by_tol'][tol] = None
        results.append(entry)
    return results

def _summarize(results):
    agg = {'by_tol': {}}
    for tol in ['1e-9','1e-8']:
        jacs=[]; rhos=[]; n_eval=0
        for r in results:
            blk = r['by_tol'].get(tol)
            if blk and blk.get('K_used',0)>0:
                n_eval += 1
                j = blk.get('jaccard')
                if j is not None: jacs.append(float(j))
                rho = blk.get('spearman_on_intersection')
                if rho is not None: rhos.append(float(rho))
        agg['by_tol'][tol] = {
            'classes_evaluated': n_eval,
            'mean_jaccard': (sum(jacs)/len(jacs)) if jacs else None,
            'mean_spearman': (sum(rhos)/len(rhos)) if rhos else None
        }
    return agg

def _write(payload):
    _ensure()
    with open(OUT_RES, 'w') as f:
        json.dump(payload, f, indent=2)
    stamp = time.strftime('%Y-%m-%dT%H-%M-%SZ', time.gmtime())
    freeze = os.path.join(OUT_DIR, 'freezes', f'kkt_slack_cross_class_v2_1_{stamp}.json')
    with open(freeze, 'w') as f:
        json.dump(payload, f, indent=2)
    return freeze

def construct_packing():
    rec = _gather()
    results = _analyze(rec)
    summary = _summarize(results)
    payload = {
        'generated_at': _ts(),
        'schema': 'v2.1',
        'source_dir': SHARED,
        'class_count': len(rec),
        'summary': summary,
        'results_by_class': results
    }
    try:
        _write(payload)
    except Exception:
        pass
    # return baseline with tiny shrink
    try:
        c = np.loadtxt('storage/noesis/latest_centers.txt', dtype=float).reshape(26,2)
        r = np.loadtxt('storage/noesis/latest_radii.txt', dtype=float).reshape(26,)
    except Exception:
        centers=[]; rad=0.08
        for i in range(5):
            for j in range(6):
                if len(centers)<26:
                    centers.append([0.1+0.2*i, 0.1+0.15*j])
        c = np.array(centers, float); r = np.full(26, rad, float)
    r = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r.astype(float)
